    },
    {
      "type": "set_tax",
      "target": null,
      "amount": 24.5,
      "sub": "",
      "order": "Adjust total tax revenue target to 24.5% of GDP to slightly improve the fiscal balance."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 5.5,
      "sub": "welfare",
      "order": "Rationalize welfare spending to 5.5% of GDP to ensure fiscal prudence while protecting the most vulnerable."
    },
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 1.0,
      "sub": "",
      "order": "Invest an additional 1% of GDP into strategic infrastructure to boost productivity and growth."
    }
  ],
  "cables": [
    {
      "to": "BRA",
      "private": true,
      "text": "We reaffirm our commitment to Mercosur and look forward to strengthening our bilateral trade and economic cooperation with Brazil."
    }
  ],
  "public_statement": "My government is taking decisive, responsible steps to conquer inflation, restore fiscal health, and lay the foundations for sustainable economic growth that benefits all Argentines.",
  "standing_orders": [
    {
      "when": "inflation_above:50",
      "do": {
        "type": "monetary_policy",
        "target": null,
        "amount": 1.0,
        "sub": "",
        "order": "Raise interest rates further if inflation remains critically high."
      }
    }
  ],
  "detailed_report": "economy"
}
